import json,sys,time,urllib.request
sys.stdout.reconfigure(encoding='utf-8')
R=json.load(open('routes.json',encoding='utf-8'))
P={r['ort']:(r['geo'][0],r['geo'][1]) for r in R['rows']}
CL={}
for r in R['rows']: CL.setdefault(r['cluster'],[]).append(r['ort'])
P.update({'Hall':(47.2816648,11.5075337),'Ostermiething':(48.0470,12.8260),'Lochau':(47.5170,9.7530),
'Brixlegg-Tst':(47.4290,11.8790),'Kiefersfelden':(47.6130,12.1890),'Saalfelden':(47.4260,12.8480),
'Eugendorf':(47.8650,13.1200),'Aiglhof':(47.8050,13.0230),'Kössen-Tst':(47.6690,12.4040),
'Arlberg-Maut':(47.1300,10.2990)})
def q(url):
  for i in range(4):
    try:
      return json.load(urllib.request.urlopen(url,timeout=40))
    except Exception as e: time.sleep(2)
  raise
def route(names):
  c=';'.join(f'{P[n][1]},{P[n][0]}' for n in names)
  j=q(f'https://router.project-osrm.org/route/v1/driving/{c}?overview=false')
  r=j['routes'][0]; return round(r['distance']/1000,1), round(r['duration']/60), [round(l['distance']/1000,1) for l in r['legs']]
def trip(names):
  c=';'.join(f'{P[n][1]},{P[n][0]}' for n in names)
  j=q(f'https://router.project-osrm.org/trip/v1/driving/{c}?roundtrip=true&source=first&overview=false')
  r=j['trips'][0]; order=sorted(range(len(names)),key=lambda i:j['waypoints'][i]['waypoint_index'])
  return round(r['distance']/1000,1), round(r['duration']/60), [names[i] for i in order]
out={}
def show(k,v): out[k]=v; print(k,v)
show('Hall-Osterm-Hall',route(['Hall','Ostermiething','Hall']))
show('Hall-Lochau-Hall',route(['Hall','Lochau','Hall']))
show('Hall-Arlberg-Hall',route(['Hall','Arlberg-Maut','Hall']))
import json,sys
sys.argv=['x']
exec(open('kb23/osrm.py',encoding='utf-8').read().split("out={}")[0])
T={
'Innsbruck-Umgebung':['Innsbruck','Rum','Kematen (in Tirol)'],
'Unterinntal (Rest: Jenbach, Alpbach, Wörgl)':['Jenbach','Alpbach','Wörgl'],
'Unterinntal gesamt (Info)':['Jenbach','Brixlegg','Kramsach','Reith im Alpbachtal','Alpbach','Wörgl','Söll','Kufstein'],
'Zillertal':['Kaltenbach','Aschau im Zillertal'],
'Oberland':['Leutasch','Mieming','Landeck'],
'Kitzbühel (Rest)':['Hopfgarten (in Tirol)','Brixen im Thale','Kitzbühel','Aurach bei Kitzbühel','Erpfendorf','(leer)'],
'Kitzbühel gesamt (Info)':['Hopfgarten (in Tirol)','Brixen im Thale','Kitzbühel','Aurach bei Kitzbühel','Erpfendorf','(leer)','Fieberbrunn'],
'Kaiserwinkl (Info)':['Kössen','Walchsee'],
'Außerfern':['Pflach','Pinswang'],
'Vbg-Oberland':['Bludenz','Bürs','Nenzing','Thüringen','Ludesch','Nüziders','Schruns','St. Gallenkirch'],
'Vbg-Rheintal inkl. Bregenz/Möggers':['Feldkirch','Satteins','Rankweil','Röthis','Viktorsberg','Götzis','Mäder','Koblach','Altach','Hohenems','Dornbirn','Schwarzach','Lustenau','Bregenz','Möggers'],
'Bregenzerwald':['Bezau'],
'Vorarlberg gesamt (Info)':['Bludenz','Bürs','Nenzing','Thüringen','Ludesch','Nüziders','Schruns','St. Gallenkirch','Feldkirch','Satteins','Rankweil','Röthis','Viktorsberg','Götzis','Mäder','Koblach','Altach','Hohenems','Dornbirn','Schwarzach','Lustenau','Bregenz','Möggers','Bezau'],
'Salzburg Oberalm (Info)':['Oberalm'],
}
res={}
for k,v in T.items():
  for x in v: assert x in P,x
  d,m,o=trip(['Hall']+v); res[k]=[d,m,o]; print(k,d,m,o)
# combos with Lochau trip
for k in ['Vbg-Oberland','Vbg-Rheintal inkl. Bregenz/Möggers','Bregenzerwald','Vorarlberg gesamt (Info)']:
  d,m,o=trip(['Hall']+T[k]+['Lochau']); res['Lochau+'+k]=[d,m,o]; print('Lochau+',k,d,m, round(d-397.3,1))
# combos with Ostermiething
for k in ['Unterinntal (Rest: Jenbach, Alpbach, Wörgl)','Kitzbühel (Rest)','Zillertal']:
  d,m,o=trip(['Hall']+T[k]+['Ostermiething']); res['Osterm+'+k]=[d,m,o]; print('Osterm+',k,d,m, round(d-355.2,1))
json.dump(res,open('kb23/tours.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
